const { chromium } = require('playwright');
const { spawn } = require('child_process');
const fs = require('fs');
const output='hosted-trial-artifacts';fs.mkdirSync(output,{recursive:true});
const port=18772, origin=`http://127.0.0.1:${port}`;
const server=spawn('python3',['-m','internal.ops_mvp.hosted'],{env:{...process.env,PORT:String(port),DL_TRIAL_ORIGIN:origin,RENDER_EXTERNAL_URL:''},stdio:['ignore','pipe','pipe']});
const errors=[], flows=[];let browser;
async function ready(){for(let i=0;i<100;i++){try{if((await fetch(origin+'/health')).ok)return;}catch{}await new Promise(r=>setTimeout(r,100));}throw Error('Hosted app did not start');}
(async()=>{try{await ready();browser=await chromium.launch({headless:true});
for(const width of [360,1280]){const context=await browser.newContext({viewport:{width,height:900}}),page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(origin);await page.screenshot({path:`${output}/${width}-start.png`,fullPage:true});await page.locator('#start').click();await page.locator('#trial').waitFor({state:'visible'});
for(let stage=0;stage<14;stage++){if(await page.locator('#switch-next').count())await page.locator('#switch-next').click();await page.locator('#advance').waitFor({state:'visible'});if(stage===10){await page.locator('#preview').click();await page.locator('#rows li').last().waitFor();if(await page.locator('#rows li').count()!==14)throw Error('Preview row count');}await page.locator('#advance').click();if(stage<13)await page.waitForFunction(s=>document.querySelector('#next .eyebrow')?.textContent.startsWith(`${s+2} /`),stage);else await page.getByText('전체 흐름 완료',{exact:true}).waitFor();
if([4,10,13].includes(stage)){await page.screenshot({path:`${output}/${width}-stage-${stage+1}.png`,fullPage:true});}const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);if(overflow)throw Error(`Overflow ${width}/${stage}`);flows.push(`${width}:step:${stage+1}`);}
await page.selectOption('#role','client_b');await page.getByText('다른 고객의 자료는 보이지 않습니다',{exact:true}).waitFor();if(await page.getByText('근거가 이어지는 보고서',{exact:true}).count())throw Error('Other client saw report');flows.push(`${width}:other-client-hidden`);await page.selectOption('#role','operator');await page.getByText('근거가 이어지는 보고서',{exact:true}).waitFor();const dl=page.waitForEvent('download');await page.locator('#download').first().click();const download=await dl;await download.saveAs(`${output}/${width}-fictional-case.json`);const report=JSON.parse(fs.readFileSync(`${output}/${width}-fictional-case.json`));if(!report.synthetic_only||report.case.reports.length!==3||report.case.state!=='closed')throw Error('Downloaded report invalid');flows.push(`${width}:download`);await page.reload();await page.getByText('전체 흐름 완료',{exact:true}).waitFor();flows.push(`${width}:resume`);
const visitor=await browser.newContext(),other=await visitor.newPage();await other.goto(origin);await other.locator('#start').click();await other.locator('#advance').waitFor();if(await other.getByText('근거가 이어지는 보고서',{exact:true}).count())throw Error('Visitor shared state');flows.push(`${width}:visitor-isolation`);await visitor.close();await context.close();}
if(errors.length)throw Error(errors.join('; '));fs.writeFileSync(`${output}/report.json`,JSON.stringify({flows,errors,screenshots:8},null,2));console.log(JSON.stringify({flows:flows.length,errors,screenshots:8}));
}finally{if(browser)await browser.close();server.kill('SIGTERM');}})().catch(e=>{fs.writeFileSync(`${output}/failure.txt`,e.stack);console.error(e);process.exitCode=1;});
